'use strict';

// Every value below is a fictional design fixture. No application APIs are used.
const $ = (selector, parent = document) => parent.querySelector(selector);
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n = value => Number(value).toLocaleString('en-US');
const icons = {
  home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
  flag:'M5 22V3m0 0c5-4 9 4 14 0v11c-5 4-9-4-14 0',
  user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',
  plus:'M12 5v14M5 12h14', back:'m14 5-7 7 7 7', arrow:'M5 12h14m-6-6 6 6-6 6',
  chevron:'m9 5 7 7-7 7', down:'m6 9 6 6 6-6', close:'m6 6 12 12M18 6 6 18',
  chart:'M4 20V4m0 16h17M8 16v-4m5 4V7m5 9V3',
  steps:'M8 13c-3 1-5-1-5-4s2-7 4-6 4 8 1 10m7 7c-3 1-5-1-5-4s2-7 4-6 4 8 1 10M5 16l1 3m12-12 1 3',
  run:'M14 4a1.8 1.8 0 1 0 0-.01M5 10l5-3 4 3 5 1M10 7l-2 7 6 3-1 5M8 14l-3 5H2',
  clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',
  heart:'M20 5c-2-2-6-1-8 2-2-3-6-4-8-2-5 5 2 11 8 16 6-5 13-11 8-16Z',
  check:'m5 12 4 4L20 5', shield:'M12 2 3 6v6c0 5 5 8 9 10 4-2 9-5 9-10V6Zm-5 10 3 3 7-7',
  people:'M10 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0M2 20v-2a5 5 0 0 1 10 0v2M18 9a3 3 0 1 0-3-4m0 9a5 5 0 0 1 7 4v2',
  mail:'M3 5h18v14H3Zm0 1 9 7 9-7', dots:'M5 12h.01M12 12h.01M19 12h.01',
  info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6m0-10v.01',
  file:'M14 2H5v20h14V7Zm0 0v5h5M8 12h8m-8 4h8',
  lock:'M5 10h14v11H5Zm3 0V6a4 4 0 0 1 8 0v4m-4 5v2',
  exit:'M9 3H3v18h6m5-14 5 5-5 5m-7-5h12',
  refresh:'M20 7V2m0 5h-5m5 0A9 9 0 1 0 21 14',
  settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6m-7 0v6',
  watch:'M8 6V2h8v4M8 18v4h8v-4M6 6h12v12H6Zm6 3v3l2 1',
  pause:'M8 4v16M16 4v16'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.arrow}"/></svg>`;
const routes = {home:'Home / Today',challenges:'Challenges',leaderboard:'Friend leaderboard',goal:'Personal goal',activity:'Activity detail',create:'Create a challenge',lobby:'Friend lobby',invitation:'Invitation',agreement:'Agreement review',receipt:'Agreement receipt',result:'Result & review',review:'Ask for a review',reviewReceipt:'Review receipt',you:'You',health:'Apple Health',privacy:'Privacy & safety',support:'Help & support',leave:'Leave a challenge',exit:'Exit receipt',existing:'Existing challenges',community:'Community'};
const mainScreens=['home','challenges','leaderboard','goal','create','invitation','agreement','result','you'];
const query = new URLSearchParams(location.search);
const state = {screen:routes[query.get('screen')] ? query.get('screen') : 'home',history:[],day:5,detail:'standings',overview:'active',expanded:null,result:'open',consent:false,context:'invitation',invitation:'pending',reviewReason:'',reviewNote:'',reviewSaved:false,reviewAt:'Sep 15, 2026 · 9:12 AM Central Time',paused:false,shared:false,health:'connected',supportSaved:false,left:false,personalLeft:false,leaveType:'friends',receipt:false,savedReceipt:null,savedAgreementHTML:'',viewSaved:false,formError:''};
const draft = {step:1,kind:'leaderboard',metric:'steps',name:'Weekly steps',start:'2026-09-16',days:'7',amount:'20',target:'50000',distance:'5',time:'25:00',friends:['Maya','Jordan']};
const metricInfo={steps:{label:'Steps',unit:'steps',icon:'steps',target:'50000'},exercise:{label:'Exercise minutes',unit:'minutes',icon:'heart',target:'150'},distance:{label:'Running distance',unit:'km',icon:'run',target:'20'},timed:{label:'Timed run',unit:'minutes',icon:'clock',target:'25:00'}};
const week = [5840,7120,4860,6340,9240,5220,null];
const dayNames=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const shortDays=['M','T','W','T','F','S','S'];
const sim = `<p class="sim-note"><strong>Simulated stakes — no real money moves.</strong>Nothing can be paid out or redeemed.</p>`;
const button=(text,action,style='primary',extra='')=>`<button class="${style} ${style==='primary'||style==='secondary'?'glass':''}" data-action="${action}" ${extra}>${text}</button>`;
const goto=(text,page,style='text-action')=>`<button class="${style}" data-go="${page}">${text}</button>`;
const navRow=(title,detail,page,symbol='chevron')=>`<button class="nav-row" data-go="${page}"><span class="row-main"><strong>${title}</strong>${detail?`<small>${detail}</small>`:''}</span>${icon(symbol)}</button>`;
const fact=(title,value)=>`<div class="fact"><dt>${title}</dt><dd>${value}</dd></div>`;
const disclosure=(title,body,open=false)=>`<details ${open?'open':''}><summary>${title}</summary><div class="details-body">${body}</div></details>`;
const sectionTitle=(title,action='')=>`<div class="section-title"><h2>${title}</h2>${action}</div>`;
function nav(active){return `<nav class="bottom-nav glass" aria-label="Main navigation" style="--selected:${['home','challenges','you'].indexOf(active)}">${['home','challenges','you'].map((id,i)=>`<button data-go="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(['home','flag','user'][i])}<span>${['Home','Challenges','You'][i]}</span></button>`).join('')}</nav>`;}
function toolbar(title,root=false){return `<header class="toolbar">${root?`<div class="wordmark">GameTime<span class="signal-mark" aria-hidden="true"><i></i><i></i><i></i></span></div>`:`<button class="icon-button glass" data-action="back" aria-label="Go back">${icon('back')}</button><span class="toolbar-title">${title}</span>`}<button class="icon-button glass" data-${root?'go="create"':'go="home"'} aria-label="${root?'Create a challenge':'Close and go Home'}">${icon(root?'plus':'close')}</button></header>`;}
function shell(title,body,tab='challenges',root=false){return toolbar(title,root)+`<main class="scroll-content" id="screen-content">${body}</main>`+nav(tab);}
function heading(title,subtitle=''){return `<div class="screen-heading"><div><h1 tabindex="-1">${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div></div>`;}
function segment(items,selected,action){return `<div class="segmented glass" role="group" aria-label="${action==='overview'?'Challenge status':'Challenge detail'}" style="--segments:${items.length};--selected:${items.findIndex(x=>x[0]===selected)}">${items.map(([id,label])=>`<button data-${action}="${id}" aria-pressed="${id===selected}">${label}</button>`).join('')}</div>`;}
function chart(){const x=i=>29+i*48;return `<div class="chart" aria-label="Daily steps, September 7 through 13"><div class="chart-lens glass" id="chart-lens"></div><div class="chart-plot"><svg viewBox="0 0 366 161" role="img" aria-label="Daily step totals. Monday 5,840; Tuesday 7,120; Wednesday 4,860; Thursday 6,340; Friday 9,240; Saturday 5,220 so far; Sunday has not started.">${[18,73,128].map((y,i)=>`<line class="grid-line" x1="17" y1="${y}" x2="328" y2="${y}"/><text class="axis-label" x="335" y="${y+3}">${['10k','5k','0'][i]}</text>`).join('')}${week.map((v,i)=>`<rect data-bar="${i}" class="bar ${v===null?'future':''} ${i===state.day?'selected':''}" x="${x(i)-10}" y="${v===null?120:128-v/10000*110}" width="20" height="${v===null?8:v/10000*110}"/><text class="axis-label" text-anchor="middle" x="${x(i)}" y="154">${shortDays[i]}</text>`).join('')}<line id="crosshair" class="crosshair" x1="${x(state.day)}" x2="${x(state.day)}" y1="0" y2="128"/></svg><input class="chart-range" id="day-scrubber" type="range" min="0" max="6" step="1" value="${state.day}" aria-label="Explore daily steps" aria-valuetext=""/></div><div class="chart-caption"><span>Sep 7–13, 2026</span><span>Drag to explore · Daily steps</span></div></div>`;}
function updateChart(day,announce=false){state.day=Number(day);const d=state.day, v=week[d];const lens=$('#chart-lens');if(!lens)return;const text=`${dayNames[d]}, September ${d+7}: ${v===null?'Not started':n(v)+' steps'}. ${d===5?'So far · updated 9:38 AM':d===6?'No total yet':'Day complete'}`;lens.style.setProperty('--lens-x',`${Math.max(21,Math.min(79,8+d*13.1))}%`);lens.innerHTML=`<span><b>${dayNames[d].slice(0,3)}, Sep ${d+7}</b> · ${d===5?'So far':d===6?'Upcoming':'Complete'}</span><strong>${v===null?'Not started':n(v)+' <span style="display:inline;color:inherit;font-size:11px">steps</span>'}</strong>`;document.querySelectorAll('[data-bar]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.bar)===d));$('#crosshair').setAttribute('x1',29+d*48);$('#crosshair').setAttribute('x2',29+d*48);$('#day-scrubber').setAttribute('aria-valuetext',text);if(announce)$('#announcement').textContent=text;}
function home(){return shell('',`<div class="screen-heading"><h1 tabindex="-1">Today</h1><span class="date">Saturday, September 12</span></div><section class="hero-metric" aria-label="Your activity this week"><p class="metric-label">Your steps this week</p><div class="big-number">38,620</div><p class="metric-context"><span class="status-dot"></span>Through today, 9:38 AM · 6 days</p>${chart()}</section>${state.invitation==='pending'?`<button class="invitation-row" data-go="invitation">${icon('mail')}<span class="row-main"><strong>Maya invited you</strong><small>Next week’s kilometres · Review invitation</small></span>${icon('chevron')}</button>`:''}${state.reviewSaved?navRow('Your review request','Weekly steps · View saved request','reviewReceipt','file'):''}${sectionTitle('With friends',goto('View all '+icon('arrow'),'challenges'))}<button class="activity-row" data-go="leaderboard"><span class="rank-number">02</span><span class="row-main"><strong>Weekly steps</strong><small>3 people · Sep 7–13</small></span><span class="row-value"><strong>38,620</strong><small>your steps</small></span>${icon('chevron')}</button><div class="own-goal"><button data-go="goal"><span><strong>Your exercise goal</strong><span class="small" style="display:block;margin-top:4px">Just for you · Sep 7–13</span></span><span class="goal-total">95<small> / 150 min</small></span></button><div class="progress-line" style="--progress:63.33%"><span></span></div></div><p class="source-line">${icon('watch')}Updated from Apple Health at 9:38 AM</p>`,'home',true);}
function challenges(){const active=state.overview==='active';let body=heading('Challenges','Your weeks, your people, your own goals.')+segment([['active','Active'],['upcoming','Upcoming'],['finished','Finished']],state.overview,'overview');if(active){body+=sectionTitle('With friends')+(state.left?`<p class="small">You’ve left Weekly steps in this preview.</p>`:`<button class="activity-row" data-go="leaderboard"><span class="row-icon">${icon('steps')}</span><span class="row-main"><strong>Weekly steps</strong><small>Leaderboard · Day 6 of 7</small></span><span class="row-value"><strong>2nd</strong><small>of 3 people</small></span>${icon('chevron')}</button>`)+sectionTitle('Just for you')+`<button class="activity-row" data-go="goal"><span class="row-icon">${icon('heart')}</span><span class="row-main"><strong>A little more movement</strong><small>Exercise minutes · Sep 7–13</small></span><span class="row-value"><strong>95</strong><small>of 150 min</small></span>${icon('chevron')}</button>`;}else if(state.overview==='upcoming'){body+=state.receipt?navRow('Your saved agreement','View the example receipt','receipt','file'):'';body+=state.invitation==='pending'?navRow('Next week’s kilometres','From Maya · Your own 20 km goal','invitation','mail'):`<div class="empty"><h2>No invitations to review.</h2><p>You can create a challenge whenever you’re ready.</p></div>`;}else{body+=navRow('Weekly steps','Sample result · Sep 15, 2026','result','flag');if(state.left)body+=button('<span class="row-main"><strong>You left Weekly steps</strong><small>Your example exit receipt</small></span>'+icon('exit'),'view-friend-exit','nav-row');if(state.personalLeft)body+=button('<span class="row-main"><strong>You left your exercise goal</strong><small>Your example exit receipt</small></span>'+icon('exit'),'view-personal-exit','nav-row');}body+=`<div class="action-stack">${button('Create a challenge '+icon('plus'),'create')}</div>`+navRow('GameTime community','Join details aren’t ready','community','people');return shell('',body,'challenges',true);}
function rankRows(){return [['Maya','41,280','Last update 9:32 AM'],['You','38,620','Last update 9:38 AM'],['Jordan','35,450','Last update 9:27 AM']].map(([name,total,updated],i)=>`<button class="rank-row ${i===1?'current':''}" data-rank="${i}" aria-expanded="${state.expanded===i}"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><span class="rank-person">${name}<small>${updated}</small></span><span class="rank-result">${total}<small>steps</small></span>${icon('down')}</button>${state.expanded===i?`<div class="rank-timeline"><p class="timeline-note">${name==='You'?'Your':name+'’s'} shared challenge activity</p>${(i===1?[['Today so far','5,220'],['Friday, Sep 11','9,240'],['Sep 7–10','24,160']]:i===0?[['Today so far','6,300'],['Friday, Sep 11','8,980'],['Sep 7–10','26,000']]:[['Today so far','4,010'],['Friday, Sep 11','7,430'],['Sep 7–10','24,010']]).map(([date,steps])=>`<div class="timeline-item"><span>${date}</span><strong>${steps} steps</strong></div>`).join('')}${i===1?goto('Explore your week '+icon('arrow'),'home'):''}</div>`:''}`).join('');}
function leaderboard(){if(state.left)return shell('With friends',heading('You’ve left Weekly steps.')+`<p class="subtitle">Your agreement stays in your history.</p><div class="action-stack">${button('View your exit receipt','view-friend-exit')}</div>`);let body=heading('Weekly steps','Sep 7–13, 2026 · 3 people')+`<div class="hero-metric"><p class="metric-label">Your total so far</p><div class="big-number">38,620<span class="unit">steps</span></div><p class="metric-context">2nd of 3 · Day 6 of 7</p></div>`+segment([['standings','Standings'],['week','Your week'],['rules','Rules']],state.detail,'detail');if(state.detail==='standings')body+=`<div class="leaderboard-header"><span>Person</span><span>Total steps</span></div>${rankRows()}<p class="small" style="margin-top:17px">Highest total wins. There’s no step target.</p><p class="source-line">${icon('watch')}Only activity in this challenge appears here.</p>`;if(state.detail==='week')body+=chart()+`<div class="info-block"><h2>Today is still in progress.</h2><p>Your final total can change as Apple Health updates. Sunday hasn’t started yet.</p></div>`;if(state.detail==='rules')body+=`<dl class="facts">${fact('Starts','Sep 7, 2026 · 12:00 AM')}${fact('Ends','Sep 14, 2026 · 12:00 AM')}${fact('Time zone','Central Time')}${fact('Simulated entry','$20 per person · Fee $0')}</dl>`+fullRules('leaderboard','steps')+sim+button('Leave this challenge','leave-friends','secondary');return shell('With friends',body);}
function goal(){
  if(state.personalLeft)return shell('Just for you',heading('You’ve left this goal.')+`<p class="subtitle">Your agreement stays in your history.</p><div class="action-stack">${button('View your exit receipt','view-personal-exit')}</div>`,'home');
  return shell('Just for you',heading('A little more movement','Your exercise goal · Sep 7–13, 2026')+`<section class="performance-slab" aria-label="Your exercise progress"><div class="performance-readout"><div class="performance-number">95<span>min</span></div><p>Exercise minutes<br>this week</p></div><div class="performance-track" role="img" aria-label="95 of 150 exercise minutes: Tuesday 28, Thursday 35, Saturday 32."><div><span style="flex:28"></span><span style="flex:35"></span><span style="flex:32"></span></div></div><p class="performance-goal">Your agreed goal · 150 minutes across the week</p><div class="performance-context"><p><strong>3</strong> days with exercise so far</p><p><strong>7</strong> full days in this goal</p></div></section><section class="personal-story"><div><h2>This goal<br>is yours.</h2>${icon('lock')}</div><p>There’s no ranking. Your personal activity and result stay private.</p></section>${sectionTitle('Recent activity')}<button class="activity-row" data-go="activity"><span class="row-icon">${icon('run')}</span><span class="row-main"><strong>Saturday morning run</strong><small>Today · 7:42 AM · Apple Watch</small></span><span class="row-value"><strong>32</strong><small>exercise min</small></span>${icon('chevron')}</button><div class="activity-row"><span class="row-icon">${icon('heart')}</span><span class="row-main"><strong>Thursday afternoon</strong><small>Sep 10 · Apple Watch</small></span><span class="row-value"><strong>35</strong><small>exercise min</small></span></div><div class="activity-row"><span class="row-icon">${icon('steps')}</span><span class="row-main"><strong>Tuesday evening</strong><small>Sep 8 · Apple Watch</small></span><span class="row-value"><strong>28</strong><small>exercise min</small></span></div><p class="source-line">${icon('watch')}Exercise minutes come from Apple Health.</p>${dateWindow('2026-09-07','2026-09-14')}${entrySummary('20',true,'Simulated amount')}${fullRules('personal','exercise')}${sim}<div class="action-stack">${button('Leave this goal','leave-personal','secondary')}</div>`,'home');
}
function activity(){return shell('Your activity',heading('Saturday morning run','September 12, 2026 · 7:42 AM')+`<p class="metric-label">Running distance</p><div class="big-number">5.24<span class="unit">km</span></div><div class="metric-grid"><div><strong>34:18</strong><span>time including pauses</span></div><div><strong>6:33</strong><span>average min / km</span></div></div>${sectionTitle('Kilometre by kilometre')}<table class="activity-splits"><caption class="sr-only">Fictional running splits</caption><thead><tr><th scope="col">Distance</th><th scope="col">Time</th></tr></thead><tbody>${[['1 km','6:42',93],['2 km','6:36',91],['3 km','6:25',87],['4 km','6:31',89],['5 km','6:29',88],['Last 0.24 km','1:35',23]].map(([km,time,w])=>`<tr><td>${km}<span class="split-bar" style="--width:${w}%"></span></td><td>${time}</td></tr>`).join('')}</tbody></table><div class="info-block"><h2>32 exercise minutes added.</h2><p>Apple Health records exercise minutes separately from workout time. Those minutes count toward your exercise goal.</p></div>${navRow('A little more movement','95 of 150 exercise minutes','goal')}<p class="small" style="margin-top:18px">This activity is not an attempt toward a timed-running goal.</p>`,'home');}
function dateDisplay(iso){const [y,m,d]=iso.split('-').map(Number);return new Date(Date.UTC(y,m-1,d)).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});}
function endDate(){const d=new Date(draft.start+'T00:00:00Z');if(!Number.isFinite(d.getTime())||!Number.isFinite(Number(draft.days)))return '2026-09-23';d.setUTCDate(d.getUTCDate()+Number(draft.days));return d.toISOString().slice(0,10);}
function targetText(metric=draft.metric){return metric==='timed'?`${esc(draft.distance)} km in under ${esc(draft.time)}`:`${n(draft.target)} ${metricInfo[metric].unit}`;}
function field(label,key,value,type='text',help='',attrs=''){return `<label class="form-field"><span>${label}</span><input type="${type}" data-field="${key}" value="${esc(value)}" ${attrs}>${help?`<small>${help}</small>`:''}</label>`;}
function choices(items,selected,action){return `<div class="choice-list">${items.map(([id,title,sub,sym])=>`<button class="choice" data-${action}="${id}" aria-pressed="${id===selected}"><span class="choice-symbol">${icon(sym)}</span><span class="row-main"><strong>${title}</strong><small>${sub}</small></span><span class="radio-mark" aria-hidden="true"></span></button>`).join('')}</div>`;}
function create(){const s=draft.step;const titles=['Make it your kind of week.','Choose what counts.','Set the dates.','Your example amount.','Check your draft.'];let body=`<div class="step-progress" aria-hidden="true">${[1,2,3,4,5].map(x=>`<span class="${x<=s?'done':''}"></span>`).join('')}</div><p class="step-count">Step ${s} of 5</p>`+heading(titles[s-1]);if(s===1)body+=choices([['leaderboard','A friend leaderboard','Compare totals with 1–5 friends. No target.','chart'],['goals','Individual goals with friends','Each person chooses their own goal.','people'],['personal','A goal just for you','Choose a target. Keep your progress private.','user']],draft.kind,'kind');if(s===2){body+=choices(Object.entries(metricInfo).map(([id,m])=>[id,m.label,id==='timed'?'Your best whole run, including pauses.':id==='exercise'?'Apple Health exercise minutes.':id==='distance'?'Your running distance across all days.':'Your steps across all days.',m.icon]),draft.metric,'metric');if(draft.metric==='timed')body+=field('Running distance (km)','distance',draft.distance,'number','An example distance for this design study.','min="0.1" step="0.1"');if(draft.kind!=='leaderboard')body+=draft.metric==='timed'?field('Your time goal · under minutes:seconds','time',draft.time,'text','Equal to the time goal does not meet it.','inputmode="decimal" placeholder="25:00"'):field(`Your goal (${metricInfo[draft.metric].unit})`,'target',draft.target,'number',draft.kind==='goals'?'Only you choose your goal. Your friends propose their own.':'Your goal belongs only to you.',`min="1" step="${draft.metric==='distance'?'.1':'1'}"`);else body+=`<div class="notice"><strong>No target to set.</strong><p>${draft.metric==='timed'?'The fastest run over the agreed distance wins.':'The highest total wins.'} Equal best results share the win.</p></div>`;if(draft.metric==='timed')body+=`<p class="small">Timed running is a design example. We still need to confirm how accurately the run distance can be measured before it’s available.</p>`;}if(s===3)body+=field('Challenge name','name',draft.name,'text','A short name everyone will recognise.','maxlength="55"')+`<div class="form-row">${field('Start date','start',draft.start,'date','','min="2026-09-14" max="2026-10-12"')}${field('Number of days','days',draft.days,'number','','min="1" max="30" step="1"')}</div><dl class="facts">${fact('Time zone','Central Time')}${fact('Days','1–30 full calendar days')}</dl><p class="small">Each day starts at midnight. In this example, choose a start from September 14 through October 12, 2026.</p>`;if(s===4)body+=field('Simulated amount (USD)','amount',draft.amount,'number','Choose a whole-dollar example from $1 to $500.','min="1" max="500" step="1"')+`<dl class="facts">${fact('Fee','$0')}${fact('Real money','$0')}</dl><p class="subtitle">${draft.kind==='personal'?'If we confirm you missed the goal after review, your simulated amount stays unallocated.':'Possible simulated results depend on everyone’s agreed rules. You’ll review them before you agree.'}</p>${sim}`;if(s===5)body+=draftSummary()+`<div class="notice"><strong>${draft.kind==='personal'?'Your goal, ready to review.':'Choose your people next.'}</strong><p>${draft.kind==='personal'?'Read the full goal rules before agreeing.':'Your friends still need to review and agree. Nothing starts from this draft.'}</p></div>`;body+=`<p class="error" role="alert" id="form-error">${esc(state.formError)}</p><div class="action-stack">${button(s===5?(draft.kind==='personal'?'Review goal rules':'Choose friends'):'Continue '+icon('arrow'),'create-next')}${s>1?button('Back','back','secondary'):''}<p>Local preview · nothing is sent or scheduled.</p></div>`;return shell('Create a challenge',body);}
function draftSummary(){return `<h2>${esc(draft.name)}</h2><dl class="facts">${fact('Format',draft.kind==='personal'?'Just for you':draft.kind==='goals'?'Individual friend goals':'Friend leaderboard')}${fact('Activity',metricInfo[draft.metric].label)}${draft.kind!=='leaderboard'?fact('Your goal',targetText()):draft.metric==='timed'?fact('Agreed distance',esc(draft.distance)+' km'):''}${fact('Starts',dateDisplay(draft.start)+' · 12:00 AM')}${fact('Ends',dateDisplay(endDate())+' · 12:00 AM')}${fact('Time zone','Central Time')}${fact('Simulated amount',`$${n(draft.amount)}${draft.kind==='personal'?'':' per person'} · Fee $0`)}</dl>`;}
function friendTarget(name){const offset={Maya:1,Jordan:.75,Alex:1.1,Riley:.9,Sam:.8}[name];if(draft.metric==='timed')return `${esc(draft.distance)} km in under ${{Maya:'26:00',Jordan:'28:00',Alex:'24:00',Riley:'29:00',Sam:'30:00'}[name]}`;return n(Math.round(Number(draft.target)*offset))+` ${metricInfo[draft.metric].unit}`;}
function lobby(){return shell('Choose friends',heading('A week with your people.','Select 1–5 friends for this example.')+`<div class="notice"><strong>${draft.kind==='goals'?'Everyone proposes their own goal.':'No targets. Just the agreed activity.'}</strong><p>${draft.kind==='goals'?'These fictional friends have proposed the goals below. You can’t edit another person’s goal.':'You’ll all review the same activity, dates and simulated amount.'}</p></div><div class="activity-row"><span class="row-main"><strong>You</strong><small>${draft.kind==='goals'?targetText():'Creator · '+metricInfo[draft.metric].label}</small></span></div>${['Maya','Jordan','Alex','Riley','Sam'].map(name=>`<label class="member-choice"><input type="checkbox" data-friend="${name}" ${draft.friends.includes(name)?'checked':''}><span>${name}<small>${draft.kind==='goals'?'Proposed '+friendTarget(name):'Fictional friend'}</small></span></label>`).join('')}<p class="error" id="form-error" role="alert">${esc(state.formError)}</p><div class="action-stack">${button('Review the complete agreement','lobby-next')}<p>These choices stay in this preview.</p></div>`);}
// Presentation-only summaries. Terms, consent and saved agreements keep their existing behavior.
function dateWindow(start,end){
  const days=Math.round((new Date(end+'T00:00:00Z')-new Date(start+'T00:00:00Z'))/86400000);
  return `<section class="date-window" aria-label="Challenge dates"><div class="date-window-points"><div><span class="date-window-label">Starts</span><time datetime="${esc(start)}T00:00:00"><strong>${dateDisplay(start)}</strong><span>12:00 AM</span></time></div><span class="date-window-arrow">${icon('arrow')}</span><div><span class="date-window-label">Ends</span><time datetime="${esc(end)}T00:00:00"><strong>${dateDisplay(end)}</strong><span>12:00 AM</span></time></div></div><p class="date-window-zone">${days} full ${days===1?'day':'days'} <span aria-hidden="true">·</span> Central Time</p></section>`;
}
function entrySummary(amount,personal=false,label='Simulated entry'){
  return `<div class="entry-summary">${icon('file')}<div><span>${label}</span><strong>$${n(amount)}${personal?'':' per person'} <span>· Fee $0</span></strong></div></div>`;
}
function proposedGoals(people){
  return `<div class="people-goals">${people.map(([name,target,context])=>`<div class="person-goal"><strong>${esc(name)}</strong><p>${target}</p><small>${context}</small></div>`).join('')}</div>`;
}
function agreementOverview(invite,kind,metric){
  const personal=kind==='personal',leaderboard=kind==='leaderboard';
  const start=invite?'2026-09-16':draft.start,end=invite?'2026-09-23':endDate();
  const label=invite?'Your own running goal':leaderboard?(metric==='timed'?'Agreed distance':'No activity target.'):'Your goal';
  const value=invite?'20':metric==='timed'?(leaderboard?esc(draft.distance):esc(draft.time)):leaderboard?metricInfo[metric].label:n(draft.target);
  const unit=invite?'km':metric==='timed'?(leaderboard?'km':''):leaderboard?'':metricInfo[metric].unit;
  const detail=!invite&&!leaderboard?targetText():'';
  const people=invite?[['You','20 km','Your own goal'],['Maya','20 km','Proposed by Maya'],['Jordan','15 km','Proposed by Jordan']]:draft.friends.map(name=>[name,friendTarget(name),'Proposed by '+esc(name)]);
  return `${!invite?`<h2 class="agreement-name">${esc(draft.name)}</h2>`:''}<p class="agreement-format">${icon(metricInfo[metric].icon)}<span>${personal?'Just for you':leaderboard?'Friend leaderboard':'Individual friend goals'} <span aria-hidden="true">·</span> ${metricInfo[metric].label}</span></p><section class="agreement-focus" aria-label="Agreed activity"><div class="intent-number ${value.length>7?'intent-number-long':''}">${value}${unit?`<span>${unit}</span>`:''}</div><p>${label}</p>${detail?`<p class="agreement-target">${detail}</p>`:''}</section>${!personal?(kind==='goals'?`<section class="agreement-people" aria-label="Everyone’s own goals">${proposedGoals(people)}</section>`:`<p class="agreement-roster">${icon('people')}<span>${['You',...draft.friends].map(esc).join(' · ')}</span></p>`):''}${dateWindow(start,end)}${entrySummary(invite?'20':draft.amount,personal,personal?'Simulated amount':'Simulated entry')}`;
}
function invitation(){
  if(state.invitation==='declined')return shell('Invitation',heading('Invitation declined.')+`<div class="info-block"><h2>You haven’t joined.</h2><p>Your choice is saved in this preview. No message was sent.</p></div><div class="action-stack">${button('Back to Challenges','challenges')}</div>`);
  return shell('From Maya',heading('Next week’s kilometres','Individual goals with friends')+`<section class="invitation-focus" aria-label="Your proposed running goal"><div class="intent-number">20<span>km</span></div><div class="invitation-message"><p>Your proposed running goal</p><strong>A full week.<br>Your own total.</strong></div></section>${dateWindow('2026-09-16','2026-09-23')}<section class="invitation-people"><h2>Everyone has their own goal</h2>${proposedGoals([['Maya','20 km','Proposed by Maya'],['Jordan','15 km','Proposed by Jordan']])}<p class="small">Everyone can meet their own goal. Opening this invitation doesn’t mean you’ve agreed.</p></section>${entrySummary('20')}${sim}<div class="action-stack">${button('Review invitation '+icon('arrow'),'review-invitation')}${button('Decline invitation','decline','secondary')}</div>`);
}
function fullRules(kind,metric){const personal=kind==='personal',goals=kind==='goals';const metricRule=metric==='steps'?'We add up your steps across the full window.':metric==='exercise'?'We add up Apple Health exercise minutes, not workout duration.':metric==='distance'?'We add up your running distance across the full window.':`Your best whole run over the agreed distance counts, including pauses. ${kind!=='leaderboard'?'Your time must be strictly under your target. Equal time does not meet it.':'The fastest time wins.'}`;const allocation=personal?'Meet your goal and your simulated entry returns. A confirmed miss leaves it unallocated. If we can’t confirm the result, the goal doesn’t count and your entry returns.':goals?'People who meet their goals get their own simulated entries back and evenly share the entries from confirmed misses. People whose results we can’t confirm get their entries back. Leftover cents and a group where everyone misses stay unallocated. With fewer than two people whose results we can confirm, the challenge doesn’t count and all entries return.':'The highest total, or fastest whole timed run, wins. Equal best results share the win and split the simulated pool equally. Leftover cents stay unallocated. If we can’t confirm any person’s result, the leaderboard doesn’t count and all entries return.';return disclosure('What counts?',`We count activity recorded by Apple Watch in Apple Health during these exact dates. Manually added or imported activity doesn’t count. ${metricRule} Missing or unreadable data never counts as a loss.`,true)+disclosure('Possible results and simulated amounts',allocation+' Fee $0. Nothing can be paid out or redeemed.')+disclosure('Final checks and review','We accept the final activity update for 24 hours after the challenge ends, and corrections for 48 hours after the end. We aim to publish the first result within 72 hours after the end. You get 48 full hours from the actual result notice to ask for a review. We pause the simulated result while reviewing it. The review period for our decision runs for 72 hours from your request. Delays never shorten your review time.')+disclosure('Leaving and privacy',`You can leave before the result is final and your simulated entry returns. ${personal?'Your personal activity and result stay private.':'The friend challenge continues only with at least two people whose results we can confirm. Otherwise it doesn’t count and all entries return. Friends see only the agreed challenge activity and result, not your other activity.'}`)+(!personal?disclosure('Everyone agrees before the start','Everyone reviews the complete roster, goals where applicable, dates, source and simulated amount. If any of those change, everyone needs to agree again. If anyone hasn’t agreed when the challenge starts, the challenge is cancelled and all simulated entries return.'): '');}
function agreement(){if(state.viewSaved&&state.savedAgreementHTML)return shell('Saved agreement',state.savedAgreementHTML);if(state.context==='draft'&&(!draft.start||!Number.isInteger(Number(draft.days))||Number(draft.days)<1||Number(draft.days)>30||!validTarget()||!draft.name.trim()||!Number.isInteger(Number(draft.amount))||Number(draft.amount)<1||Number(draft.amount)>500))return shell('Your agreement',heading('Finish your draft first.')+`<p class="subtitle">Check your dates, goal and simulated amount before reviewing the full agreement.</p><div class="action-stack">${button('Back to your draft','create')}</div>`);const invite=state.context==='invitation',kind=invite?'goals':draft.kind,metric=invite?'distance':draft.metric;let body=heading('Review & agree.',invite?'Next week’s kilometres':'Read what you’re signing up for.')+agreementOverview(invite,kind,metric);body+=`<div class="agreement-outcome"><strong>${kind==='leaderboard'?'No activity target.':kind==='personal'?'Your personal goal.':'Everyone has their own goal.'}</strong><p>${kind==='leaderboard'?'Highest total or fastest time wins. Equal best results share the win. Missing data can mean the leaderboard doesn’t count.':kind==='personal'?'Meeting your goal returns your simulated entry. A confirmed miss leaves it unallocated. Missing data alone never means a miss.':'Meeting your goal returns your simulated entry. People who meet their goals share entries from confirmed misses. Missing data alone never means a miss.'} You can leave before the result is final.</p></div>${fullRules(kind,metric)}${sim}<div class="consent-block"><label class="check-row"><input id="consent" type="checkbox" ${state.consent?'checked':''}><span>I’ve read this challenge and agree to its rules, dates, and simulated amount.</span></label>${button('Agree in this preview','agree','primary',state.consent?'':'disabled')}<p class="small" style="text-align:center;margin-top:15px">Nothing is sent. No real money moves.</p></div>`;return shell('Your agreement',body);}
function receipt(){const r=state.savedReceipt||{personal:false,name:'Next week’s kilometres',start:'Sep 16, 2026',amount:'20',waiting:'Jordan'};return shell('Your receipt',`<div class="status-symbol">${icon('check')}</div><h1 class="receipt-title" tabindex="-1">${r.personal?'Your example goal is scheduled.':'You’ve agreed.'}</h1><p class="subtitle">Your choice is saved in this preview.</p><dl class="facts">${fact('Challenge',esc(r.name))}${fact('Your response','Agreed in this preview')}${fact('Starts',r.start+' · 12:00 AM')}${fact('Time zone','Central Time')}${fact('Simulated amount','$'+n(r.amount)+(r.personal?'':' per person')+' · Fee $0')}</dl>${!r.personal?`<div class="notice"><strong>Waiting for ${esc(r.waiting)}.</strong><p>Everyone still needs to agree to the same rules before the start. If anyone hasn’t agreed, the challenge is cancelled and all simulated entries return.</p></div>`:''}${sim}<div class="action-stack">${button('Back to Challenges','challenges')}${button('View your agreement','view-agreement','secondary')}</div>`);}
function saveAgreement(){const invitation=state.context==='invitation';state.savedReceipt=Object.freeze({personal:!invitation&&draft.kind==='personal',name:invitation?'Next week’s kilometres':draft.name,start:invitation?'Sep 16, 2026':dateDisplay(draft.start),amount:invitation?'20':draft.amount,waiting:invitation?'Jordan':draft.friends.join(' and ')});const copy=$('#screen-content').cloneNode(true);copy.querySelector('h1').textContent='Your saved agreement.';copy.querySelector('.consent-block').innerHTML=`<div class="notice"><strong>You agreed to these rules in this preview.</strong><p>A later draft does not change this agreement.</p></div>${button('Back to your receipt','receipt','secondary')}`;state.savedAgreementHTML=copy.innerHTML;state.viewSaved=false;}
function result(){const missing=state.result==='missing',tie=state.result==='tie';let body=heading('Weekly steps','Sample result · September 15, 2026')+segment([['open','Review open'],['tie','Equal totals'],['missing','Missing data']],state.result,'result')+`<span class="pill">${state.reviewSaved?'Your review is open':'Result to review'}</span><div class="outcome-number">${missing?'—':'52,310'}</div><p class="result-status">${missing?'We couldn’t confirm your final total.':tie?'steps · Equal highest total with Maya':'steps · Highest total this week'}</p>`;if(!missing)body+=`<div class="activity-row"><span class="row-main"><strong>Maya</strong></span><span class="row-value"><strong>${tie?'52,310':'49,870'}</strong><small>steps</small></span></div><div class="activity-row"><span class="row-main"><strong>Jordan</strong></span><span class="row-value"><strong>45,260</strong><small>steps</small></span></div>`;body+=`<div class="info-block"><h2>${missing?'Missing data alone doesn’t mean anyone lost.':state.reviewSaved?'Your review is open.':'Time to check the result.'}</h2><p>${missing?'We can’t confirm this leaderboard. It won’t count if a final total remains missing. Everyone’s simulated entry will return when the result is confirmed.':state.reviewSaved?'Your example request is saved. The simulated result is paused.':'The result is not final yet. You can ask us to review it.'}</p></div><dl class="facts">${fact('Notice saved','Sep 15, 2026 · 9:00 AM')}${fact('Ask for a review by','Sep 17, 2026 · 9:00 AM')}${fact('Time zone','Central Time')}</dl>${disclosure('Proposed simulated result',`${missing?'Expected return: $20 to each person.':tie?'Expected return: $30 each to you and Maya; $0 to Jordan.':'Expected return: $60 to you; $0 to Maya and Jordan.'} Fee $0. These are proposed simulated results. No return has been recorded. Nothing can be paid out or redeemed.`,true)}${sim}<div class="action-stack">${button(state.reviewSaved?'View your review request':'Ask us to review this result',state.reviewSaved?'reviewReceipt':'review')}${button('Back to Challenges','challenges','secondary')}</div>`;return shell('Challenge result',body);}
function review(){return shell('Result review',heading('What should we check?','Weekly steps · Sample result, September 15')+`<p class="subtitle">We’ll pause the simulated result while we review your request.</p><div class="review-options">${['My activity is missing','My total looks wrong','Something else'].map(text=>`<label><input type="radio" name="review-reason" value="${text}" ${state.reviewReason===text?'checked':''}>${text}</label>`).join('')}</div><label class="form-field"><span>What happened? (optional)</span><textarea id="review-note" maxlength="600" placeholder="Tell us which day or activity to check.">${esc(state.reviewNote)}</textarea></label><p class="small">Ask by September 17, 2026, 9:00 AM Central Time.</p><p class="error" id="form-error" role="alert">${esc(state.formError)}</p><div class="action-stack">${button('Save example review request','save-review')}${button('Go back','back','secondary')}<p>This stays in the preview. No request is sent.</p></div>`);}
function reviewReceipt(){return shell('Your review request',`<div class="status-symbol">${icon('file')}</div><h1 class="receipt-title" tabindex="-1">Your review request is saved.</h1><p class="subtitle">The simulated result is paused.</p><dl class="facts">${fact('Challenge','Weekly steps')}${fact('Result notice','Sep 15, 2026 · 9:00 AM Central Time')}${fact('Request saved',state.reviewAt)}${fact('Reason',esc(state.reviewReason||'My activity is missing'))}</dl><div class="info-block"><h2>Your note</h2><p>${esc(state.reviewNote||'No additional note.')}</p></div><p class="small">This is an example receipt. No request was sent.</p><div class="action-stack">${button('Back to the result','result')}</div>`);}
function you(){return shell('',`<div class="screen-heading"><h1 tabindex="-1">You</h1>${icon('user')}</div><p class="profile-name">Mason</p><p class="subtitle">@mason · Fictional profile</p><div class="metric-grid"><div><strong>3</strong><span>active days this week</span></div><div><strong>95</strong><span>exercise minutes</span></div></div>${sectionTitle('Your account')}${navRow('Apple Health',state.health==='connected'?'Example activity available':'Connect to see your activity','health','heart')}${navRow('Privacy & safety','Sharing and new commitments','privacy','shield')}${navRow('Help & support','Get help with a challenge','support','info')}${navRow('Existing challenges','Your earlier agreements','existing','file')}<div class="info-block"><h2>Your activity belongs to you.</h2><p>You choose which challenges to join. Personal goals stay private.</p></div>`,'you',true);}
function health(){return shell('Apple Health',heading('Your activity, in one place.','GameTime reads activity recorded by your Apple Watch in Apple Health.')+`<div class="status-symbol">${icon('watch')}</div><span class="pill">${state.health==='connected'?'Example activity available':'Not connected in this example'}</span><dl class="facts">${Object.values(metricInfo).map(m=>fact(m.label,state.health==='connected'?(m.label==='Timed run'?'Not ready for use':'Example activity found'):'No activity checked')).join('')}</dl><div class="notice"><strong>You control access.</strong><p>We’ll ask before reading your activity. You can change access in Apple Health. Completing the permission prompt alone doesn’t confirm that activity is ready.</p></div><div class="action-stack">${button(state.health==='connected'?'Preview disconnected state':'Preview connected state','health-toggle')}${button('Back to You','you','secondary')}<p>No Health data is read in this preview.</p></div>`,'you');}
function privacy(){return shell('Privacy & safety',heading('Your choice, every time.')+(state.paused?`<div class="notice"><strong>New commitments are paused.</strong><p>Turn this off below when you want to create or agree to a new challenge.</p></div>`:'')+`<div class="setting-row"><span class="row-main"><strong>Pause new commitments</strong><small>Existing challenges, reviews and exits remain available. This doesn’t cancel anything you’ve agreed to.</small></span><button class="switch" role="switch" aria-label="Pause new commitments" aria-checked="${state.paused}" data-action="pause"></button></div><div class="setting-row"><span class="row-main"><strong>Share personal progress</strong><small>Off by default. This example only changes the setting shown here; it doesn’t share activity.</small></span><button class="switch" role="switch" aria-label="Share personal progress" aria-checked="${state.shared}" data-action="share"></button></div><div class="info-block"><h2>Private by default.</h2><p>Friends see activity you agreed to share in a challenge. They don’t see your other activity. Turning sharing off does not erase an earlier agreement.</p></div>${navRow('Leave a challenge','You can leave before the result is final','leave','exit')}${navRow('Get help with a person or challenge','No message is sent from this preview','support','shield')}`,'you');}
function support(){return shell('Help & support',heading(state.supportSaved?'Your example note is saved.':'How can we help?')+(state.supportSaved?`<div class="info-block"><h2>Nothing was sent.</h2><p>Your note stays here until you reload this preview.</p></div><div class="action-stack">${button('Back to You','you')}</div>`:`<p class="subtitle">For a challenge result, use the review form so you can keep the result and your request together.</p>${navRow('Review Weekly steps','Ask us to check a result','review','file')}<label class="form-field"><span>Your note</span><textarea id="support-note" maxlength="600" placeholder="Tell us what you need help with."></textarea></label><p class="error" id="form-error" role="alert">${esc(state.formError)}</p><div class="action-stack">${button('Save example support note','save-support')}<p>No message is sent.</p></div>`),'you');}
function leave(){const personal=state.leaveType==='personal';return shell('Leave a challenge',heading(personal?'Leave your exercise goal?':'Leave Weekly steps?')+`<div class="info-block"><h2>You can stop here.</h2><p>You don’t need to give a reason. ${personal?'Your goal will end.':'Your participation will end. The friend challenge continues only if at least two people whose results we can confirm remain.'}</p></div><dl class="facts">${fact('Your simulated entry','$20')}${fact('After leaving','Your entry returns')}${fact('Fee','$0')}</dl><p class="subtitle">Leaving doesn’t count as a loss. Your earlier agreement stays in your history. A saved exit doesn’t mean the final result or simulated return has already been recorded.</p>${sim}<div class="action-stack">${button('Leave in this preview','confirm-leave')}${button('Keep participating','back','secondary')}</div>`);}
function exitReceipt(){return shell('Your exit receipt',`<div class="status-symbol">${icon('check')}</div><h1 class="receipt-title" tabindex="-1">You’ve left ${state.leaveType==='personal'?'your goal':'Weekly steps'}.</h1><p class="subtitle">Your example exit is saved.</p><div class="info-block"><h2>Simulated return update pending.</h2><p>Your $20 simulated entry will return. This receipt does not record a return. No real money moved.</p></div><p class="small">Your agreement stays in this preview’s history.</p><div class="action-stack">${button('Back to Challenges','challenges')}</div>`);}
function existing(){return shell('Existing challenges',heading('Your earlier agreements.')+`<div class="empty"><h2>No earlier challenges in this preview.</h2><p>In the app, your previous Personal challenges and the original rules you agreed to stay available here.</p>${button('Back to You','you')}</div>`,'you');}
function community(){return shell('GameTime community',heading('A shared goal. Your own progress.')+`<div class="info-block"><h2>Join details aren’t ready.</h2><p>We’ll show the exact step goal, dates and simulated amount before you decide to join.</p></div><p class="subtitle">Your name and individual activity stay private. Group counts only appear when at least five people have joined and the update is at least 15 minutes old.</p><div class="action-stack">${button('Back to Challenges','challenges')}<p>No launch settings have been selected in this study.</p></div>`);}
const views={home,challenges,leaderboard,goal,activity,create,lobby,invitation,agreement,receipt,result,review,reviewReceipt,you,health,privacy,support,leave,exit:exitReceipt,existing,community};
const notes={home:['Every day,<br>in focus.','Drag across the chart. A floating glass lens reveals the exact total and update status for each day.'],leaderboard:['The table<br>tells the story.','Tap a person to expand their shared activity. Names, totals and time all keep a precise place in the grid.'],goal:['One goal.<br>Your own pace.','Personal progress gets its own space. Activity rows explain where the total came from, without a social ranking.'],create:['Every choice<br>has a consequence.','A short sequence keeps format, activity, dates and simulated amount distinct. A leaderboard never asks for a target.'],agreement:['Clarity before<br>commitment.','Rules and consent stay on solid, readable content. The primary action waits for a deliberate agreement.'],result:['A result you<br>can question.','The result, review deadline and proposed simulated return are separate facts. Missing data never implies a loss.']};
function render(focus=false){const active=document.activeElement;const inApp=$('#app').contains(active);const focusAttr=['data-kind','data-metric','data-overview','data-detail','data-result','data-action','data-rank'].find(a=>active?.hasAttribute(a));const focusSelector=focusAttr?`[${focusAttr}="${CSS.escape(active.getAttribute(focusAttr))}"]`:active?.id?'#'+CSS.escape(active.id):null;const previousScroll=$('#screen-content')?.scrollTop||0;$('.phone').dataset.screen=state.screen;$('#app').innerHTML=(views[state.screen]||home)();if(state.screen==='home'&&state.left)$('main [data-go="leaderboard"]')?.remove();if(['home','challenges'].includes(state.screen)&&state.personalLeft){const goalLink=$('main [data-go="goal"]');(goalLink?.closest('.own-goal')||goalLink)?.remove();}$('#screen-picker').value=state.screen;document.querySelectorAll('.screen-link').forEach(el=>el.classList.toggle('active',el.dataset.go===state.screen));const note=notes[state.screen]||['A complete<br>visual system.','Follow the buttons through invitations, agreements, results and safe exits. Every person and activity is fictional.'];$('#notes-title').innerHTML=note[0];$('#notes-body').textContent=note[1];if($('#chart-lens'))updateChart(state.day);if(focus)$('#screen-content h1')?.focus({preventScroll:true});else{if(inApp&&focusSelector)$(focusSelector,$('#app'))?.focus({preventScroll:true});$('#screen-content').scrollTop=previousScroll;}document.title=`GameTime — Signal · ${routes[state.screen]}`;const u=new URL(location.href);u.searchParams.set('screen',state.screen);history.replaceState(null,'',u);}
function go(page){if(!routes[page])return;if(state.screen!==page)state.history.push(state.screen);if(page==='create'&&state.paused){state.screen='privacy';$('#announcement').textContent='New commitments are paused. Turn the pause off here to create a challenge.';}else{state.screen=page;if(page==='agreement'){state.consent=false;}if(page==='review')state.formError='';}render(true);}
function back(){if(state.screen==='create'&&draft.step>1){draft.step--;state.formError='';render(true);return;}state.screen=state.history.pop()||'home';state.formError='';render(true);}
function error(text){state.formError=text;const el=$('#form-error');if(el){el.textContent=text;el.scrollIntoView({block:'center',behavior:'auto'});}else $('#announcement').textContent=text;}
function validTarget(){if(draft.kind==='leaderboard')return true;if(draft.metric==='timed')return /^\d{1,3}:[0-5]\d$/.test(draft.time)&&draft.time!=='0:00'&&draft.time!=='00:00';return Number(draft.target)>0&&Number.isFinite(Number(draft.target))&&(draft.metric==='distance'||Number.isInteger(Number(draft.target)));}
function advance(){state.formError='';if(draft.step===2){if(draft.metric==='timed'&&(!(Number(draft.distance)>0)||!Number.isFinite(Number(draft.distance))))return error('Enter a running distance greater than zero to continue.');if(!validTarget())return error(draft.metric==='timed'?'Enter a time greater than zero as minutes:seconds, such as 25:00.':'Enter a positive goal to continue. Steps and exercise minutes use whole numbers.');}if(draft.step===3){const d=Number(draft.days);if(!draft.name.trim())return error('Add a challenge name to continue.');if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.start)||draft.start<'2026-09-14'||draft.start>'2026-10-12')return error('Choose a start date from September 14 through October 12, 2026.');if(!Number.isInteger(d)||d<1||d>30)return error('Choose between 1 and 30 full days.');}if(draft.step===4&&(!Number.isInteger(Number(draft.amount))||Number(draft.amount)<1||Number(draft.amount)>500))return error('Choose a whole-dollar simulated amount from $1 to $500.');if(draft.step===5){state.context='draft';state.viewSaved=false;state.consent=false;go(draft.kind==='personal'?'agreement':'lobby');}else{draft.step++;render(true);}}
document.addEventListener('click',e=>{const el=e.target.closest('button, [data-go]');if(!el)return;if(el.dataset.go){go(el.dataset.go);return;}if(el.dataset.setting){const key=el.dataset.setting;const options={appearance:['light','dark'],material:['glass','solid'],contrast:['normal','more'],motion:['full','reduced']}[key];setSetting(key,document.documentElement.dataset[key]===options[0]?options[1]:options[0]);return;}for(const k of ['overview','detail','result'])if(el.dataset[k]){state[k]=el.dataset[k];if(k==='result'){state.reviewSaved=false;state.reviewReason='';state.reviewNote='';}render();return;}if(el.dataset.rank!==undefined){const i=Number(el.dataset.rank);state.expanded=state.expanded===i?null:i;const scroll=$('#screen-content').scrollTop;render();$('#screen-content').scrollTop=scroll;$(`[data-rank="${i}"]`)?.focus({preventScroll:true});return;}if(el.dataset.kind){draft.kind=el.dataset.kind;state.consent=false;render();return;}if(el.dataset.metric){draft.metric=el.dataset.metric;draft.target=metricInfo[draft.metric].target;state.consent=false;render();return;}const a=el.dataset.action;if(a==='back')return back();if(a==='create-next')return advance();if(a==='lobby-next'){if(draft.friends.length<1)return error('Choose at least one friend to review the agreement.');state.context='draft';state.viewSaved=false;state.consent=false;go('agreement');return;}if(a==='review-invitation'){state.context='invitation';state.viewSaved=false;state.consent=false;go('agreement');return;}if(a==='decline'){state.invitation='declined';render(true);return;}if(a==='agree'&&state.consent){if(state.paused){go('privacy');$('#announcement').textContent='New commitments are paused. Turn the pause off before agreeing.';return;}saveAgreement();state.receipt=true;if(state.context==='invitation')state.invitation='agreed';go('receipt');return;}if(a==='view-agreement'){state.viewSaved=Boolean(state.savedAgreementHTML);go('agreement');return;}if(a==='save-review'){if(!state.reviewReason)return error('Choose what you’d like us to check, then save your request.');state.reviewSaved=true;go('reviewReceipt');return;}if(a==='pause'){state.paused=!state.paused;render();return;}if(a==='share'){state.shared=!state.shared;render();return;}if(a==='health-toggle'){state.health=state.health==='connected'?'disconnected':'connected';render();return;}if(a==='save-support'){if(!$('#support-note').value.trim())return error('Add a note about what happened, then save it.');state.supportSaved=true;go('support');return;}if(a==='leave-friends'||a==='leave-personal'){state.leaveType=a==='leave-personal'?'personal':'friends';go('leave');return;}if(a==='view-personal-exit'||a==='view-friend-exit'){state.leaveType=a==='view-personal-exit'?'personal':'friends';go('exit');return;}if(a==='confirm-leave'){if(state.leaveType==='personal')state.personalLeft=true;else state.left=true;go('exit');return;}if(routes[a])go(a);});
document.addEventListener('input',e=>{if(e.target.id==='day-scrubber')updateChart(e.target.value);if(e.target.dataset.field){draft[e.target.dataset.field]=e.target.value;state.consent=false;}if(e.target.id==='review-note')state.reviewNote=e.target.value;});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='screen-picker')return go(el.value);if(['appearance','material','contrast','motion'].includes(el.id))return setSetting(el.id,el.value);if(el.id==='consent'){state.consent=el.checked;$('[data-action="agree"]').disabled=!state.consent;}if(el.name==='review-reason')state.reviewReason=el.value;if(el.dataset.friend){if(el.checked&&!draft.friends.includes(el.dataset.friend))draft.friends.push(el.dataset.friend);else if(!el.checked)draft.friends=draft.friends.filter(x=>x!==el.dataset.friend);state.consent=false;}if(el.id==='day-scrubber')updateChart(el.value,true);});
document.addEventListener('pointermove',e=>{const el=e.target.closest('.glass');if(!el||document.documentElement.dataset.motion==='reduced'||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const r=el.getBoundingClientRect();el.style.setProperty('--gx',`${(e.clientX-r.left)/r.width*100}%`);el.style.setProperty('--gy',`${(e.clientY-r.top)/r.height*100}%`);});
function setSetting(key,value){const allowed={appearance:['light','dark'],material:['glass','solid'],contrast:['normal','more'],motion:['full','reduced']};if(!allowed[key]?.includes(value))return;document.documentElement.dataset[key]=value;$('#'+key).value=value;const u=new URL(location.href);u.searchParams.set(key,value);history.replaceState(null,'',u);}
$('#screen-list').innerHTML=mainScreens.map((id,i)=>`<button class="screen-link" data-go="${id}"><span class="index">${String(i+1).padStart(2,'0')}</span>${routes[id]}</button>`).join('');
$('#screen-picker').innerHTML=Object.entries(routes).map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
for(const key of ['appearance','material','contrast','motion']){if(query.has(key))setSetting(key,query.get(key));}
render();
